  "intake": {
    "sections": [
      {
        "name": "engagement",
        "fields": [
          {
            "key": "label",
            "comment": "A non-identifying session label (e.g. \"Engagement N\"), never a client name."
          },
          {
            "key": "substrate",
            "comment": "\"self\" (the practice's own system) | \"client\" (external engagement); filled-intake location per the header rule"
          },
          {
            "key": "stage",
            "comment": "discovery | audit | build | care"
          },
          {
            "key": "nda_contract_status",
            "comment": "pending | signed  (pre-signature deliverables are drafts, held for release)"
          }
        ]
      },
      {
        "name": "design_system",
        "fields": [
          {
            "key": "source",
            "comment": "figma | code | tokens-file | none-yet"
          },
          {
            "key": "token_spec",
            "comment": "e.g. DTCG 2025.10, if a token set exists"
          },
          {
            "key": "serves_via_mcp",
            "comment": "true | false  (is the system retrieved through the Design System MCP?)"
          },
          {
            "key": "component_inventory",
            "comment": "named components in scope, if known"
          },
          {
            "key": "known_drift",
            "comment": "a one-line note on suspected drift, if any (the audit confirms it)"
          },
          {
            "key": "component_source",
            "comment": "path/glob to the component catalog (Storybook glob, components dir, or a manifest json)"
          },
          {
            "key": "component_format",
            "comment": "json-manifest | storybook | code | figma | none"
          },
          {
            "key": "figma_file_key",
            "comment": "design-system Figma file key (auth is via the MCP; key only, never a token)"
          },
          {
            "key": "figma_app_file_key",
            "comment": "optional application/screens Figma file key, when separate from the DS file"
          },
          {
            "key": "description_target",
            "comment": "where token/field descriptions get written: DTCG $description | a DESIGN.md tokens: block | field_provenance"
          }
        ]
      },
      {
        "name": "api",
        "fields": [
          {
            "key": "spec",
            "comment": "path/URL to the OpenAPI spec, when the app has one"
          },
          {
            "key": "schema",
            "comment": "path/glob to the schema definitions the spec points into"
          },
          {
            "key": "handlers",
            "comment": "path/glob to the request handlers (auth + entitlement are read here, not from the spec)"
          }
        ]
      },
      {
        "name": "app",
        "fields": [
          {
            "key": "routes",
            "comment": "path/glob to the route definitions (the surface list is grounded from here)"
          },
          {
            "key": "run_url",
            "comment": "optional running URL, for a live read alongside the code"
          }
        ]
      },
      {
        "name": "deliverable",
        "fields": [
          {
            "key": "root",
            "comment": "where finished artifacts land: <engagement folder>/deliverables (gitignored, main workspace)"
          },
          {
            "key": "classification",
            "comment": "default footer for produced internal files (e.g. \"HeyHi Confidential\", or the client's own scheme)"
          }
        ]
      },
      {
        "name": "practice_areas_in_scope",
        "fields": [
          {
            "key": "practice_areas_in_scope",
            "comment": "The area ids (os/foundations/registry.yaml) this engagement touches. Governs which foundations load conditionally. Example shape (not a rule): [6, 7, 8]"
          }
        ]
      },
      {
        "name": "constraints",
        "fields": [
          {
            "key": "accessibility_target",
            "comment": "the WCAG level and the jurisdiction's named standard, if a claim is made"
          },
          {
            "key": "brand_voice_source",
            "comment": "where the client's voice lives (never HeyHi's voice for client work)"
          },
          {
            "key": "voice_prohibited",
            "comment": "resolved banned-word list (the execution form of brand_voice_source), when a skill produces copy"
          },
          {
            "key": "dash_rule",
            "comment": "em-dash policy for produced copy: max-2-per-document | zero | none"
          },
          {
            "key": "do_not_automate",
            "comment": "engagement-specific judgment calls that stay human, on top of the standing line"
          }
        ]
      },
      {
        "name": "remediation",
        "fields": [
          {
            "key": "model",
            "comment": "the owner's next-step model in their own words (e.g. \"Jira epics\", \"service tiers\", \"internal backlog\")"
          },
          {
            "key": "map",
            "comment": "finding-pattern -> recommended next step, in the owner's vocabulary (keeps consulting framing out of the method)"
          }
        ]
      },
      {
        "name": "boundary",
        "fields": [
          {
            "key": "retained_moat_touched",
            "comment": "true | false  (does this engagement touch the evaluator / populated corpus / calibration?)"
          },
          {
            "key": "hermetic_seal_confirmed",
            "comment": "true | false  (no client name in any tracked artifact)"
          }
        ]
      }
    ]
  },
